/// <param name="RefreshToken">The session's current refresh token.</param>
public sealed record RefreshSessionRequest(
    [property: JsonPropertyName("refreshToken")] string RefreshToken);

/// <summary>A template rendered with the sample values.</summary>
/// <param name="Subject">The rendered subject.</param>
/// <param name="Html">The rendered HTML part.</param>
/// <param name="Text">The rendered text part, generated from the HTML when the template has none.</param>
public sealed record RenderedEmail(
    [property: JsonPropertyName("subject")] string Subject,
    [property: JsonPropertyName("html")] string Html,
    [property: JsonPropertyName("text")] string Text);

/// <summary>An active session of a user: one signed in device or browser.</summary>
/// <param name="Id">The session ID.</param>
/// <param name="CreatedAt">When the user signed in.</param>
/// <param name="LastRefreshedAt">When the session last traded its refresh token.</param>
/// <param name="UserAgent">The user agent that signed in, at most 512 characters; null when none was sent.</param>
/// <param name="Sdk">The SDK that signed in, from <c>X-Orvano-SDK</c>; null when none was sent.</param>
/// <param name="IpAddress">The IP address last seen for the session; null when unknown.</param>
/// <param name="Current">Whether this is the session making the call.</param>
public sealed record Session(
    [property: JsonPropertyName("id")] string Id,
    [property: JsonPropertyName("createdAt")] DateTimeOffset CreatedAt,
    [property: JsonPropertyName("lastRefreshedAt")] DateTimeOffset LastRefreshedAt,
    [property: JsonPropertyName("userAgent")] string? UserAgent,
    [property: JsonPropertyName("sdk")] string? Sdk,
    [property: JsonPropertyName("ipAddress")] string? IpAddress,
    [property: JsonPropertyName("current")] bool Current);

/// <summary>One page of a user's active sessions, newest first.</summary>
/// <param name="Items">The sessions on this page.</param>
/// <param name="NextCursor">Pass it as <c>cursor</c> to get the next page; null on the last page.</param>
public sealed record SessionPage(
    [property: JsonPropertyName("items")] IReadOnlyList<Session> Items,
    [property: JsonPropertyName("nextCursor")] string? NextCursor);

/// <summary>A session's tokens. Send the access token as <c>Authorization: Bearer</c>; trade the refresh token for a new pair before the access token expires. The SDKs do both for you.</summary>
/// <param name="AccessToken">An ES256 JWT, valid for 15 minutes.</param>
/// <param name="AccessTokenExpiresAt">When the access token expires.</param>
/// <param name="RefreshToken">Trades itself for a new pair once; keep it secret.</param>
/// <param name="RefreshTokenExpiresAt">When the session ends unless it refreshes first: 30 days idle, or 365 days after sign in.</param>
/// <param name="SessionId">The session ID, also the <c>sid</c> claim of the access token.</param>
public sealed record SessionTokens(
    [property: JsonPropertyName("accessToken")] string AccessToken,
    [property: JsonPropertyName("accessTokenExpiresAt")] DateTimeOffset AccessTokenExpiresAt,
    [property: JsonPropertyName("refreshToken")] string RefreshToken,
    [property: JsonPropertyName("refreshTokenExpiresAt")] DateTimeOffset RefreshTokenExpiresAt,
    [property: JsonPropertyName("sessionId")] string SessionId);

/// <summary>A project's token signing key as the console shows it; never the key itself.</summary>
/// <param name="Id">The key ID, the <c>kid</c> of the tokens it signs.</param>
/// <param name="Status"><c>active</c> signs new tokens; <c>retiring</c> only verifies them until <c>retireAfter</c>.</param>
/// <param name="CreatedAt">When the key was created.</param>
/// <param name="RetireAfter">When a retiring key leaves the JWKS; null for the active key.</param>
public sealed record SigningKey(
    [property: JsonPropertyName("id")] string Id,
    [property: JsonPropertyName("status")] SigningKeyStatus Status,
    [property: JsonPropertyName("createdAt")] DateTimeOffset CreatedAt,
    [property: JsonPropertyName("retireAfter")] DateTimeOffset? RetireAfter);

/// <summary>A project's signing keys, the active one first.</summary>
/// <param name="Keys">The keys.</param>
public sealed record SigningKeys(
    [property: JsonPropertyName("keys")] IReadOnlyList<SigningKey> Keys);

/// <summary>Stored SMTP settings. The password is never returned.</summary>
/// <param name="Host">The SMTP server.</param>
/// <param name="Port">The port.</param>
/// <param name="Security">How the connection is secured.</param>
/// <param name="Username">The username, if the server needs one.</param>
/// <param name="HasPassword">True when a password is stored.</param>
/// <param name="FromEmail">The address emails are sent from.</param>
/// <param name="FromName">The name shown beside the From address.</param>
/// <param name="ReplyTo">Where replies go; null means the From address.</param>
/// <param name="UpdatedAt">When the settings last changed.</param>
public sealed record SmtpSettings(
    [property: JsonPropertyName("host")] string Host,
    [property: JsonPropertyName("port")] int Port,
    [property: JsonPropertyName("security")] SmtpSecurity Security,
    [property: JsonPropertyName("username")] string? Username,
    [property: JsonPropertyName("hasPassword")] bool HasPassword,
    [property: JsonPropertyName("fromEmail")] string FromEmail,
    [property: JsonPropertyName("fromName")] string? FromName,
    [property: JsonPropertyName("replyTo")] string? ReplyTo,
    [property: JsonPropertyName("updatedAt")] DateTimeOffset UpdatedAt);

/// <summary>SMTP settings to save or to test.</summary>
/// <param name="Host">The SMTP server: a host name, or an IPv4 or IPv6 address (no brackets). At most 253 characters.</param>
/// <param name="Port">The port, 1 to 65535.</param>
/// <param name="Security">How the connection is secured.</param>
/// <param name="Username">The username to sign in with; null for a server that needs none. Needs <c>starttls</c> or <c>tls</c>.</param>
/// <param name="Password">The password. Null keeps the stored one, which works only while the host, port, and username are the stored ones; change any of them and you must send the password again.</param>
/// <param name="FromEmail">The address emails are sent from.</param>
/// <param name="FromName">The name shown beside the From address; null for none. At most 128 characters.</param>
/// <param name="ReplyTo">Where replies go; null to use the From address.</param>
public sealed record SmtpSettingsInput(
    [property: JsonPropertyName("host")] string Host,
    [property: JsonPropertyName("port")] int Port,
    [property: JsonPropertyName("security")] SmtpSecurity Security,
    [property: JsonPropertyName("username")] string? Username,
    [property: JsonPropertyName("password")] string? Password,
    [property: JsonPropertyName("fromEmail")] string FromEmail,
    [property: JsonPropertyName("fromName")] string? FromName,
    [property: JsonPropertyName("replyTo")] string? ReplyTo);

/// <summary>A value a template can use.</summary>
/// <param name="Name">The name to write between <c>{{</c> and <c>}}</c>.</param>
/// <param name="Description">What it holds.</param>
/// <param name="Sample">The value previews and test emails use.</param>
public sealed record TemplateVariable(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("description")] string Description,
    [property: JsonPropertyName("sample")] string Sample);

/// <summary>The answer to <c>test.consolePing</c>.</summary>
/// <param name="Status">Always <c>ok</c>.</param>
public sealed record TestConsolePing(
    [property: JsonPropertyName("status")] string Status);

/// <summary>One fixed item in the <c>test.list</c> page.</summary>
/// <param name="Id"><c>item-1</c> to <c>item-5</c>.</param>
public sealed record TestItem(
    [property: JsonPropertyName("id")] string Id);

/// <summary>One page of <c>test.list</c>.</summary>
/// <param name="Items">The items on this page.</param>
/// <param name="NextCursor">Pass it as <c>cursor</c> to get the next page; null on the last page.</param>
public sealed record TestItemPage(
    [property: JsonPropertyName("items")] IReadOnlyList<TestItem> Items,
    [property: JsonPropertyName("nextCursor")] string? NextCursor);

/// <summary>The payload of the <c>test.pinged</c> event.</summary>
/// <param name="Message">Any text.</param>
/// <param name="At">When the ping happened.</param>
public sealed record TestPinged(
    [property: JsonPropertyName("message")] string Message,
    [property: JsonPropertyName("at")] DateTimeOffset At);

/// <summary>Changes to the signed in user. A field left out stays as it is.</summary>
/// <param name="Name">A new display name of at most 256 characters, or null to remove it.</param>
/// <param name="Metadata">New metadata, replacing the old: a JSON object of at most 16 KB.</param>
public sealed record UpdateAccountRequest(
    [property: JsonPropertyName("name"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] string? Name = null,
    [property: JsonPropertyName("metadata"), JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)] IReadOnlyDictionary<string, JsonElement>? Metadata = null);

/// <summary>Changes to the install settings.</summary>
/// <param name="ConsoleSignup">Who may create a console account.</param>
public sealed record UpdateInstallSettingsRequest(
    [property: JsonPropertyName("consoleSignup")] ConsoleSignupMode ConsoleSignup);

/// <summary>Changes to a member.</summary>
/// <param name="Role">The member's new role.</param>
public sealed record UpdateMemberRequest(
    [property: JsonPropertyName("role")] OrgRole Role);

/// <summary>Changes to an org.</summary>
/// <param name="Name">The new org name; trimmed, 1 to 100 characters.</param>
public sealed record UpdateOrgRequest(
    [property: JsonPropertyName("name")] string Name);

/// <summary>A password change.</summary>
/// <param name="CurrentPassword">The user's current password.</param>
/// <param name="NewPassword">The new password: 8 to 256 characters after Unicode NFKC normalization.</param>
public sealed record UpdatePasswordRequest(
    [property: JsonPropertyName("currentPassword")] string CurrentPassword,
    [property: JsonPropertyName("newPassword")] string NewPassword);

/// <summary>Changes to a platform. Its type never changes.</summary>
